import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/column/Python-Programming-Course/P01-Programming-thinking/09-Computers-dont-even-know-the-number-2.html","title":"09-用两位数，搞定全世界：计算机的二进制魔法","lang":"zh-CN","frontmatter":{"title":"09-用两位数，搞定全世界：计算机的二进制魔法","icon":"read","date":"2025-04-14T09:38:33.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1744615961000,"updatedTime":1748754423000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"bornforthis@bornforthis.cn","commits":12,"url":"https://github.com/AndersonHJB"}],"changelog":[{"hash":"ff4587c74d1c76d3aac787d3c96ea9dd9fecd743","time":1748754423000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更改文件夹名称"},{"hash":"871641c2877652b654f8565d255dea535a79ba90","time":1748751204000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"修改文件名称Python-Programming-Course"},{"hash":"b44db4c520933876a80fb48fe6f09ac7a07cceb7","time":1744696920000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"update"},{"hash":"e5a5dea359215d1119acaa0b05e1b7809e668bad","time":1744637126000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更换十进制图片，十进制图片缺少9"},{"hash":"81ce8b2f8f5643f8b22bf050ce4e1882c493191c","time":1744636535000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"添加旗语"},{"hash":"97fb5d8ac904fae7e9ce119e482684c6eb3564bc","time":1744632995000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"修改标题"},{"hash":"cd94268b5cf8ef7e8898595a92d8a4307f0f99d5","time":1744621737000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"update"},{"hash":"feaba1dac9683899f2bf75cc036abb2e939a7e3b","time":1744621523000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"图片显示"},{"hash":"93ad316e61ea2f1ffeac45e00719afc71e1ddd70","time":1744618294000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"这个问题，或许当年的莱布尼茨回答不出来，但是今天，我们可以帮他回答了：二进制，是一种特别适合计算机的语言。"},{"hash":"aba281a985a744dc7a8f4ab641e7e5723f3460ec","time":1744618004000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新文章"},{"hash":"c482a77491ee954b3fcf2c6911f65ab1f6468c21","time":1744616510000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"创建菜谱"},{"hash":"b2cf4857084504b8e646f32f48df0bd8bb3c584f","time":1744615961000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"changename"}]},"readingTime":{"minutes":8.81,"words":2644},"filePathRelative":"column/Python-Programming-Course/P01-Programming-thinking/09-Computers-dont-even-know-the-number-2.md"}`),a={name:`09-Computers-dont-even-know-the-number-2.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>在前面，我们聊到了<strong>抽象思维</strong>，其中一个很有代表性的例子就是：把图像、文字、声音这些多彩多样的信息，转化成数字。因为对计算机来说，<strong>数字才是它唯一能理解的“语言”</strong>。</p><p>但这就引出了一个有趣的问题：计算机真的能理解所有的数字吗？比如从 0 数到 9，甚至更大的数？</p><p>其实啊，计算机的“世界观”比你想象得还要简单——<strong>它只认识两个数字：0 和 1</strong>。没错，哪怕是“2”，它也不认识。</p><h2 id="_1-计算机识数的秘密" tabindex="-1"><a class="header-anchor" href="#_1-计算机识数的秘密"><span>1. 计算机识数的秘密</span></a></h2><p>你可能会感到惊讶：虽然我们日常使用的数字是由0、1、2……一直到 9 构成的，但计算机实际上只掌握两个基本符号——0 和 1。换句话说，当看到数字 2、3 或更大的数时，计算机实际上并不直接“认识”它们，而是通过某种方式将所有信息归结为 0 和 1 的组合。</p><p>人们习惯使用十进制系统，当我们从 0 数到 9，再到 10 时，其实就是在用数字表示数量的增减。</p><figure><img src="/assets/raw-20250414212456628-rlOaQrXQ.png" alt="十进制" tabindex="0" loading="lazy"><figcaption>十进制</figcaption></figure><p>那为什么我们人类选择十进制呢？很简单，因为人有十根手指，掰着数更直观、更方便。</p><figure><img src="/assets/raw-20250414153526149-DYeCeY6u.png" alt="二进制" tabindex="0" loading="lazy"><figcaption>二进制</figcaption></figure><p>但计算机可没有手指，它的“手指”只有开和关两种状态。所以，它的数数方法很特殊，只能使用 0 和 1 这两个数字，这就是二进制。</p><p>计算机依靠物理电路中开（1）和关（0）的两种状态来进行信息表达和处理。这样简洁的二元状态不仅方便设计电路，而且能够有效降低复杂性。</p><h2 id="_2-二进制与十进制的比较" tabindex="-1"><a class="header-anchor" href="#_2-二进制与十进制的比较"><span>2. 二进制与十进制的比较</span></a></h2><p>在十进制中，当数字到达 9 之后就需要进位，例如 9 后面紧接着是 10。（逢十进一）</p><p>可以看这个，比较直观：0 → 1 → 2 → 3 → … → 9 → 10（进位）</p><p>反观二进制，只有 0 和 1，一旦 1 用完，自然也需要借助进位，于是“10”便出现在二进制中。然而，这里的“10”并不代表十，而是表示二进制中的“2”。同样地，二进制中的“11”用来表示十进制的 3 。正因为如此，我们日常所使用的软件和游戏，其运行的底层逻辑都是基于由无数个 0 和 1 构成的数字编码。</p><p>我们再来看看二进制的：0 → 1 → 10（进位） → 11 → 100 → 101 → 110 → 111 → 1000 …</p><figure><img src="/assets/raw-20250414154202028-D8KJjXQs.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>二进制咋眼一看，还真像十进制。只是看起来像，因为这就好比你在看外语：单词的拼写看起来熟悉，实际意思却完全不同。</p><h2 id="_3-历史的启迪-莱布尼茨与中国八卦" tabindex="-1"><a class="header-anchor" href="#_3-历史的启迪-莱布尼茨与中国八卦"><span>3. 历史的启迪：莱布尼茨与中国八卦</span></a></h2><figure><img src="/assets/%E8%8E%B1%E5%B8%83%E5%B0%BC%E8%8C%A8%E7%94%BB%E5%83%8F-BfuYx_fx.png" alt="莱布尼茨画像" tabindex="0" loading="lazy"><figcaption>莱布尼茨画像</figcaption></figure><p>其实，二进制并非现代计算机的突然发现，它早在 300 多年前就由著名数学家莱布尼茨提出。</p><p>据记载，1701年左右，莱布尼茨创立了<strong>二进制的数学体系</strong>，这项发明背后还有一段引人入胜的小故事。</p><figure><img src="/assets/d4b4f2e13dc0b5db5ffd4fe6b31131b4-BLtRyk3F.png" alt="八卦图" tabindex="0" loading="lazy"><figcaption>八卦图</figcaption></figure><p>当时，一位传教士向中国传播文化，对中国古代的“八卦”颇有研究。八卦图由“乾、坎、艮、震、巽、离、坤、兑”八个符号组成，每一卦都是由三根横线构成，而这些横线只有两种状态：连续或断开。</p><p>这位传教士就在写给莱布尼茨的信中提到这个八卦，信中说到：每一个卦由三条横线组成，横线要么是<strong>完整的</strong>，要么是<strong>断开的</strong>。</p><ol><li><p>完整的线 → 可以看作“1”</p></li><li><p>断开的线 → 可以看作“0”</p></li></ol><p>巧妙的是，如果将连续的线视为数字“1”，而断开的线看作“0”，那么每一卦便自然转化为一个由 0 和 1 构成的数字串。</p><p>比如：</p><ul><li>“乾”卦（三条完整的线）→ 111</li><li>“坤”卦（三条断开的线）→ 000</li></ul><p>这不就是<strong>三位的二进制编码</strong>嘛！</p><p>莱布尼茨高兴坏了，觉得自己跟几千年前的中国古人产生了神秘的“心灵共鸣”，他甚至在论文里引用了八卦图，来印证自己对二进制的构想。</p><p>不过，当时的科学界并不是很在意这个发明，都觉得这二进制能有啥用啊？</p><p>这个问题，或许当年的莱布尼茨回答不出来，但是今天，我们可以帮他回答了：<strong>二进制，是一种特别适合计算机的语言</strong>。</p><h2 id="_4-为什么选择二进制" tabindex="-1"><a class="header-anchor" href="#_4-为什么选择二进制"><span>4. 为什么选择二进制？</span></a></h2><p>总结起来，二进制系统之所以成为计算机的首选，主要有以下三个原因：</p><h3 id="_4-1-完备的数值表示" tabindex="-1"><a class="header-anchor" href="#_4-1-完备的数值表示"><span>4.1 完备的数值表示</span></a></h3><p>尽管只用 0 和 1 两种符号，二进制依然能表达所有数字的信息。因为只要愿意多加几位，0 和 1 就能拼出任意大小的数字。比如二进制的 “101” 就表示十进制的 5。（省子版：用两个数字，就能表示所有的数字）</p><h3 id="_4-2-数学运算的普适性" tabindex="-1"><a class="header-anchor" href="#_4-2-数学运算的普适性"><span>4.2 数学运算的普适性</span></a></h3><figure><img src="/assets/raw-20250414162835102-G4PeYxW3.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p><s>所有十进制的运算都可以转换为二进制操作，而不牺牲计算能力。</s> 既然所有的十进制都可以转换成二进制，那么十进制的所有数学运算，二进制都可以。（省字版：可以做所有的数学运算）</p><h3 id="_4-3-电路实现的简洁性" tabindex="-1"><a class="header-anchor" href="#_4-3-电路实现的简洁性"><span>4.3 电路实现的简洁性</span></a></h3><figure><img src="/assets/raw-20250414170307538-BqGWAy45.png" alt="电子元件" tabindex="0" loading="lazy"><figcaption>电子元件</figcaption></figure><p>在硬件层面，采用简单的“开/关”电路设计远比实现十种状态（比如灯光的九个亮度级别）来得容易和稳定。（省字版：对电路来说，<strong>二进制更简单</strong>）</p><p>这种追求最简化解决方案的思路，不仅在硬件设计中得到体现，同样也深深植根于编程和软件开发的实践之中。</p><p>上面我们进行了集中的总结，接下来我们来看看实际的例子。</p><p>计算机的核心——芯片，其实就是由无数的电子元件构成的小电路。电路工作原理也很简单：电流通过（通电）就是1，不通过（断电）就是 0。</p><p>你家里的开关灯，就是最直观的例子：</p><ul><li>灯亮 → 表示“1”</li><li>灯灭 → 表示“0”</li></ul><figure><img src="/assets/%E7%81%AF-BxQi_xDT.png" alt="不同亮度的灯" tabindex="0" loading="lazy"><figcaption>不同亮度的灯</figcaption></figure><p>如果用十进制呢？一个开关只能表示两个状态，那就不够用了。为了表示从 0 到 9 的十个状态，你得配出十种不同的亮度，比如弱光、中光、强光……可想而知，这既麻烦又容易出错。</p><p>相反，<strong>二进制只要两个状态，既稳定又省事</strong>。</p><p>所以，计算机的世界选择了最简单、最可靠、最适合电子设备的方式：<strong>只说“是”或“否”，只认“通”或“断”——也就是“1”和“0”</strong>。</p><h2 id="_5-编程思维中的-简洁原则" tabindex="-1"><a class="header-anchor" href="#_5-编程思维中的-简洁原则"><span>5. 编程思维中的“简洁原则”</span></a></h2><p>其实，计算机选用二进制的原因，也反映了编程中一个非常重要的原则：<strong>简单就是高效</strong>。</p><p>你会发现，越是高级的程序员，写的代码反而越简洁。不是因为他们偷懒，而是他们更擅长把复杂的问题，转化成简单、可执行的结构。</p><p>而这正是我们在学习编程时，一直要练习的能力。当然，还是要注意：不是越简洁越好，一切讲究适当。</p><h2 id="_6-彩蛋问题-生活中的-二进制" tabindex="-1"><a class="header-anchor" href="#_6-彩蛋问题-生活中的-二进制"><span>6. 彩蛋问题：生活中的“二进制”</span></a></h2><p>总的来说，计算机利用极其简洁的二进制系统实现复杂的运算与处理，这种设计理念充分体现了“用最少的资源实现最大的功能”的智慧。</p><p>既然你已经了解了什么是二进制，那不妨动动脑筋：你能不能在生活中找出一些 <strong>只用两个状态表示信息</strong> 的例子？比如红绿灯？开关？旗语？</p><p>下一章，我们要接着探索一个新问题：如果计算机只能开关表示0和1，它是怎么完成像加法、乘法这样的计算的？这背后，其实藏着一种叫做“<strong>逻辑运算</strong>”的神奇工具。</p><h2 id="_7-旗语「选读」" tabindex="-1"><a class="header-anchor" href="#_7-旗语「选读」"><span>7. 旗语「选读」</span></a></h2><p>在写这部分的时候，我亲爱的老婆都进行了阅读。问我什么是“旗语”，我就想着马上补充一下。供你们选读～</p><h3 id="_7-1-🚩什么是旗语" tabindex="-1"><a class="header-anchor" href="#_7-1-🚩什么是旗语"><span>7.1 🚩什么是旗语？</span></a></h3><p>“旗语”是一种<strong>用旗子传递信息的方式</strong>，最早常用于军队、船队之间通信。想象一下，在没有电话、无线电的年代，两艘船隔着远远的海面，要告诉对方“快来帮忙”或者“发现敌人”，怎么做呢？</p><p>这时候，船上的人就会拿出两面小旗子，根据事先约定的动作和方向，<strong>摆出不同的姿势来表示字母或命令</strong>，就像一种“动作语言”。</p><p>比如：</p><ul><li>两只手举成“V”字，表示字母“A”</li><li>两只旗子水平伸直，表示字母“B”</li></ul><p>每一种动作都是一种“信号”。人们用望远镜一看，就能“读”出对方在说什么。</p><h3 id="_7-2-🎯为什么说旗语是-二进制-的" tabindex="-1"><a class="header-anchor" href="#_7-2-🎯为什么说旗语是-二进制-的"><span>7.2 🎯为什么说旗语是“二进制”的？</span></a></h3><p>旗语虽然看起来花里胡哨，其实背后的原理就很简单：</p><ol><li>👉 每个手里一面旗子，每次只能选择一个“姿势”</li><li>👉 每种姿势要么是 <strong>有效信号</strong>（有意义），要么是 <strong>无效信号</strong>（没意义）</li></ol><p>换句话说：<strong>要么表示什么（1），要么什么也不表示（0）</strong>。</p><p>甚至每面旗子本身也可以看成“有旗/无旗”，一种二选一的状态。</p><p>所以，旗语也是一种 <strong>只用两种状态（动作或没有动作、旗子或没有旗子）来表示信息的方式</strong>，本质上和二进制的“0”和“1”非常相似。</p><p>如果你感兴趣，还可以试试和小伙伴自制一套“旗语暗号”系统，用手、旗子、纸片都可以——玩一玩，说不定就更理解“二进制思维”了！ 😄</p>`,75)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};